const OPTCG_API_BASE = 'https://www.optcgapi.com/api'

export interface OnePieceCard {
  inventory_price: number
  market_price: number
  card_name: string
  set_name: string
  card_text: string
  set_id: string
  rarity: string
  card_set_id: string
  card_color: string
  card_type: string
  life: string
  card_cost: string
  card_power: string
  sub_types: string
  counter_amount: number
  attribute: string
  date_scraped: string
  card_image_id: string
  card_image: string
}

export interface OnePieceSet {
  set_name: string
  set_id: string
}

export const onePieceApi = {
  async searchCards(query: string): Promise<OnePieceCard[]> {
    const params = new URLSearchParams({ card_name: query })
    const response = await fetch(`${OPTCG_API_BASE}/sets/filtered/?${params}`)

    if (!response.ok) {
      throw new Error('Failed to search One Piece cards')
    }

    return response.json()
  },

  async getCard(cardSetId: string): Promise<OnePieceCard[]> {
    const response = await fetch(`${OPTCG_API_BASE}/sets/card/${cardSetId}/`)

    if (!response.ok) {
      throw new Error('Failed to get One Piece card')
    }

    return response.json()
  },

  async getSets(): Promise<OnePieceSet[]> {
    const response = await fetch(`${OPTCG_API_BASE}/allSets/`)

    if (!response.ok) {
      throw new Error('Failed to get One Piece sets')
    }

    return response.json()
  },

  async getRecentCards(): Promise<OnePieceCard[]> {
    const sets = await onePieceApi.getSets()
    if (sets.length === 0) return []

    // Get the last set (most recent)
    const latestSet = sets[sets.length - 1]
    const response = await fetch(`${OPTCG_API_BASE}/sets/${latestSet.set_id}/`)

    if (!response.ok) {
      throw new Error('Failed to get recent One Piece cards')
    }

    return response.json()
  },

  getMarketPrice(card: OnePieceCard): number | null {
    return card.market_price ?? null
  },
}
